        { VALUES ?root { wd:Q12202238 wd:Q834884 wd:Q47279819 wd:Q47460393 wd:Q125956027 wd:Q134382749 wd:Q1142663 wd:Q652446 wd:Q7894110 wd:Q2495664 wd:Q17104492 wd:Q2912517 wd:Q7935129 wd:Q7977957 wd:Q1566872 wd:Q2166280 wd:Q16089841 } ?item wdt:P31 ?root }
        UNION { VALUES ?root { wd:Q12202238 wd:Q834884 wd:Q47279819 wd:Q47460393 wd:Q125956027 wd:Q134382749 wd:Q1142663 wd:Q652446 wd:Q7894110 wd:Q2495664 wd:Q17104492 wd:Q2912517 wd:Q7935129 wd:Q7977957 wd:Q1566872 wd:Q2166280 wd:Q16089841 } ?item wdt:P279 ?root }
        UNION { VALUES ?root { wd:Q12202238 wd:Q834884 wd:Q47279819 wd:Q47460393 wd:Q125956027 wd:Q134382749 wd:Q1142663 wd:Q652446 wd:Q7894110 wd:Q2495664 wd:Q17104492 wd:Q2912517 wd:Q7935129 wd:Q7977957 wd:Q1566872 wd:Q2166280 wd:Q16089841 } BIND(?root AS ?item) }
        ?item rdfs:label ?en, ?zh.
        FILTER(LANG(?en)="en" && LANG(?zh) IN ("zh-hans", "zh-cn", "zh", "zh-tw", "zh-hant"))
        FILTER NOT EXISTS { ?item wdt:P31 wd:Q5 }
      } LIMIT 20000 }
      OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
      OPTIONAL { ?item wdt:P31 ?kind }
    }
